   122→var _ prometheus.Gatherer = (*multiRegistry)(nil)
   123→
   124→type multiRegistry struct {
   125→	gatherers []prometheus.Gatherer
   126→}
   127→
   128→func newMultiRegistry(gatherers ...prometheus.Gatherer) *multiRegistry {
   129→	return &multiRegistry{
   130→		gatherers: gatherers,
   131→	}
   132→}
   133→
   134→func (r *multiRegistry) Gather() (mfs []*dto.MetricFamily, err error) {
   135→	errs := prometheus.MultiError{}
   136→
   137→	names := make(map[string]struct{})
   138→	for _, g := range r.gatherers {
   139→		mf, err := g.Gather()
   140→		errs.Append(err)
   141→
   142→		for i := 0; i < len(mf); i++ {
   143→			m := mf[i]
   144→			_, exists := names[*m.Name]
   145→			// prevent duplicate metric names
   146→			if exists {
